class AuditMiddleware:
    def __init__(self, get_response):
        if not settings.AUDIT_DETOUR:
            raise MiddlewareNotUsed("detour disabled")   # bypass leg
        self.get_response = get_response

    def __call__(self, request):
        tag_for_replay(request)                 # inspect / modify the message
        return self.get_response(request)       # same destination on both legs
